import * as THREE from 'three';
import {configureSourceTangentMaterial,injectSourceTangentFrame,sourceTangentProgramKey} from './source-tangent-frame.js';

// Generated by tools/materials/master1uv-prepare.py. Source material math and
// renderer mappings are deliberately recorded separately in the asset document.
export const MASTER1UV_GLSL = "// LOCAL-MASTER1UV-SHADER-001. Source material math from deferred PS 6d0dd89b35.\n// Packed textures must retain all RGBA channels. Input samplers must reproduce\n// the source view's transfer function; asset format metadata includes both\n// UNORM and SRGB inputs. The runtime adapter retains that source distinction.\n// worldPosition and geometricNormal use SOURCE world axes, before browser rebasing.\n// cb[0..8] are exact per-section constants from material-analysis.json.\n// Source material inputs; BF2-NATIVE-GBUFFER-001 confirms ordinary metalness.\nstruct Master1UVSurface {\n  vec3 color;\n  vec3 tangentNormal;\n  float smoothness;\n  float materialScalar;\n  float ao;\n};\n\nMaster1UVSurface sampleMaster1UV(\n  vec2 uv, vec3 worldPosition, vec3 geometricNormal, vec4 cb[9],\n  sampler2D globalWearMap, sampler2D wearMap, sampler2D idMap,\n  sampler2D normalAOMap, sampler2D grungeMap, sampler2D anodizedMap,\n  sampler2D rubberMap, sampler2D metalCSMap, sampler2D metalNormalMap,\n  sampler2D aluminiumMap\n) {\n  vec2 tiled = uv * cb[1].xy;\n  vec4 aluminium = texture2D(aluminiumMap, tiled);\n  vec4 anodized = texture2D(anodizedMap, tiled);\n  vec4 rubberHalf = texture2D(rubberMap, tiled * 0.5);\n  vec4 rubber = texture2D(rubberMap, tiled);\n  vec4 metalCS = texture2D(metalCSMap, tiled);\n  vec4 metalNormal = texture2D(metalNormalMap, tiled * 2.0);\n  vec3 id = texture2D(idMap, uv).rgb;\n  vec4 wear = texture2D(wearMap, uv);\n  vec4 globalWear = texture2D(globalWearMap, tiled * 3.0);\n  vec4 base = texture2D(normalAOMap, uv);\n  float scratch = wear.r * (0.48 + 1.04 * globalWear.b);\n  float dirt = 2.0 * wear.g * globalWear.a;\n  float restore = clamp(2.0 * globalWear.g * wear.a / cb[2].x, 0.0, 1.0);\n\n  float smoothness0 = mix(0.8 * aluminium.a, anodized.a * cb[5].x, id.b);\n  smoothness0 = mix(smoothness0, rubberHalf.a * cb[7].x, id.g);\n  smoothness0 = mix(smoothness0, 2.0 * pow(metalCS.g, 1.5), id.r);\n  float smoothness = mix(smoothness0, 0.042311400175094604, scratch);\n  smoothness = mix(smoothness, smoothness0 + 1.0, dirt);\n  smoothness = mix(smoothness, 0.007499000057578087, wear.b);\n  smoothness = mix(smoothness, 0.8 * aluminium.a, restore);\n  float grungeZY = texture2D(grungeMap, worldPosition.zy * 0.1).g;\n  float grungeXY = texture2D(grungeMap, worldPosition.xy * 0.1).g;\n  // The VS normalizes each vertex; the PS uses the interpolated normal directly.\n  // Do not renormalize here: sat(n)+sat(-n) is abs(n) for this bounded input.\n  float grunge = mix(grungeXY, grungeZY, clamp(2.0 * abs(geometricNormal.x) - 1.0, 0.0, 1.0));\n  float grungeWeight = (1.0 - grunge) * (1.0 - abs(geometricNormal.y));\n  smoothness = mix(smoothness + 0.2, smoothness, grungeWeight);\n\n  vec3 color = mix(vec3(0.32314321398735046), cb[4].rgb, id.b);\n  color = mix(color, cb[6].rgb, id.g);\n  color = mix(color, cb[8].rgb, id.r);\n  color = mix(color, cb[3].rgb, scratch);\n  color = mix(color, vec3(0.17144109308719635), dirt);\n  color = mix(color, cb[0].rgb, wear.b);\n  color = mix(color, vec3(0.32314321398735046), restore);\n\n  vec2 baseXY = 2.0 * base.rg - 1.0;\n  float baseZ = sqrt(max(1.0 - dot(baseXY, baseXY), 0.0));\n  vec2 detail = 2.0 * aluminium.rg - 1.0;\n  detail = mix(detail, 2.0 * anodized.rg - 1.0, id.b);\n  detail = mix(detail, 2.0 * rubber.rg - 1.0, id.g);\n  detail = mix(detail, 2.0 * vec2(metalNormal.r * metalNormal.a, metalNormal.g) - 1.0, id.r);\n  detail = mix(detail, 2.0 * aluminium.rg - 1.0, wear.r + wear.g);\n\n  float scalar = mix(0.9 * (1.0 - id.g), 0.5 * metalCS.r, id.r);\n  float dirtScalar = clamp(scalar + 0.7, 0.0, 1.0);\n  scalar = mix(scalar, 0.15, scratch);\n  scalar = mix(scalar, dirtScalar, dirt);\n  scalar = mix(scalar, 0.9, restore);\n\n  Master1UVSurface result;\n  result.color = color;\n  result.tangentNormal = vec3(baseXY + detail, baseZ);\n  result.smoothness = smoothness; // Native deferred o0.z is unclamped.\n  result.materialScalar = scalar; // Native deferred o2.y is ordinary material metalness.\n  result.ao = base.a; // base.b is NOT emissive in this selected shader.\n  return result;\n}\n";
const ROLES = ['globalWear', 'wear', 'id', 'normalAO', 'grunge', 'anodized', 'rubber', 'metalCS', 'metalNormal', 'aluminium'];

export async function prepareRecoveredMasterMaterials(document, manager) {
  if (!document?.materials?.length) return { apply() {}, applied: 0, provenance: null };
  const loader = new THREE.TextureLoader(manager), textures = new Map();
  const sources = new Map(Object.values(document.sourceTextures).map(row => [row.url, row]));
  const urls = [...new Set(document.materials.flatMap(row => Object.values(row.textures)))];
  // Bound decoder work while loading the shared textures once per document.
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, urls.length) }, async () => {
    while (next < urls.length) {
      const url = urls[next++], source = sources.get(url);
      if (!source) throw new Error(`Missing Master1UV texture provenance: ${url}`);
      const texture = await loader.loadAsync(url);
      texture.colorSpace = source.colorSpace === 'srgb' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      texture.flipY = false;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textures.set(url, texture);
    }
  }));
  const recipes = new Map(document.materials.map(row => [`${row.assetId}/${row.materialId}`, row]));
  let applied = 0;
  return {
    provenance: { evidenceId: document.evidenceId, sections: recipes.size, textures: textures.size, runtimeMapping: document.runtimeMapping, limitations: document.limitations },
    get applied() { return applied; },
    apply(gltf, asset) {
      gltf.scene.traverse(mesh => {
        if (!mesh.isMesh) return;
        for (const material of [].concat(mesh.material)) {
          if (material.userData.recoveredMaster1UVShader) continue;
          const recipe = recipes.get(`${asset.id}/${material.userData.sourceMaterialId}`);
          if (!recipe) continue;
          if (!mesh.geometry.getAttribute('uv')) throw new Error(`Source Master1UV mesh has no UV0: ${asset.id}/${recipe.materialId}`);
          material.color.setRGB(1, 1, 1);
          material.roughness = 1;
          material.metalness = 0;
          material.map = material.normalMap = material.roughnessMap = material.metalnessMap = material.aoMap = material.emissiveMap = null;
          material.emissive?.setRGB(0, 0, 0);
          material.userData.recoveredMaster1UVShader = { evidenceId: document.evidenceId, sourceShader: recipe.sourceShader, runtimeMapping: document.runtimeMapping };
          material.userData.placeholder = false;
          material.userData.neutralColorApproximation = false;
          configureSourceTangentMaterial(material,mesh.geometry);
          material.onBeforeCompile = function(shader) {
            for (const role of ROLES) shader.uniforms[`bf2_master_${role}`] = { value: textures.get(recipe.textures[role]) };
            shader.uniforms.bf2_master_cb = { value: recipe.constants.map(v => new THREE.Vector4(...v)) };
            shader.vertexShader = `varying vec2 bf2_master_uv;
              varying vec3 bf2_master_world;
              varying vec3 bf2_master_geometricNormal;
            ` + shader.vertexShader;
            shader.vertexShader = shader.vertexShader.replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
              vec4 bf2_master_wp = vec4(transformed, 1.0);
              #ifdef USE_INSTANCING
                bf2_master_wp = instanceMatrix * bf2_master_wp;
              #endif
              bf2_master_world = (modelMatrix * bf2_master_wp).xyz;
              bf2_master_geometricNormal = inverseTransformDirection(transformedNormal, viewMatrix);
              bf2_master_uv = uv;
            `);
            shader.fragmentShader = `varying vec2 bf2_master_uv;
              varying vec3 bf2_master_world;
              varying vec3 bf2_master_geometricNormal;
              uniform vec4 bf2_master_cb[9];
              ${ROLES.map(role => `uniform sampler2D bf2_master_${role};`).join('\n')}
              ${MASTER1UV_GLSL}
              // Native packed tangents have not been recovered. Reconstruct the
              // UV cotangent frame rather than imposing a guessed fixed axis.
              mat3 bf2_master_tbn(vec3 position, vec3 n, vec2 uvValue) {
                vec3 q0 = dFdx(position), q1 = dFdy(position);
                vec2 st0 = dFdx(uvValue), st1 = dFdy(uvValue);
                vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
                vec3 tangent = q1perp * st0.x + q0perp * st1.x;
                vec3 bitangent = q1perp * st0.y + q0perp * st1.y;
                float invmax = inversesqrt(max(max(dot(tangent, tangent), dot(bitangent, bitangent)), 1e-16));
                return mat3(tangent * invmax, bitangent * invmax, n);
              }
            ` + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
              Master1UVSurface bf2_master_surface = sampleMaster1UV(bf2_master_uv, bf2_master_world,
                bf2_master_geometricNormal, bf2_master_cb,
                ${ROLES.map(role => `bf2_master_${role}`).join(', ')});
              diffuseColor.rgb = bf2_master_surface.color;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
              roughnessFactor = 1.0 - clamp(bf2_master_surface.smoothness, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <metalnessmap_fragment>', `#include <metalnessmap_fragment>
              metalnessFactor = clamp(bf2_master_surface.materialScalar, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_maps>', `
              mat3 bf2_master_frame = bf2_master_tbn(-vViewPosition, normal, bf2_master_uv);
              normal = normalize(bf2_master_frame * bf2_master_surface.tangentNormal);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <aomap_fragment>', `#include <aomap_fragment>
              reflectedLight.indirectDiffuse *= bf2_master_surface.ao;
            `);
            injectSourceTangentFrame(shader,this,'master1uv');
          };
          material.customProgramCacheKey = function() { return 'bf2-source-SS_DSI_Master_1UV-6d0dd89b35-v3-interpolated-grunge|' + sourceTangentProgramKey(this); };
          material.needsUpdate = true;
          applied++;
        }
      });
    },
  };
}
